"""icons.json is generated by tools/gen_icons.py and only names entities and states that exist."""

from __future__ import annotations

import importlib.util
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
_spec = importlib.util.spec_from_file_location("gen_icons", ROOT / "tools" / "gen_icons.py")
gen = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(gen)

CONTRACT = json.loads((ROOT / "tests" / "fixtures" / "entity_contract.json").read_text(encoding="utf-8"))


def test_icons_are_up_to_date():
    assert json.loads(gen.OUTPUT.read_text(encoding="utf-8")) == gen.build(), (
        "icons.json is out of date: run python tools/gen_icons.py"
    )


def test_icons_name_existing_entities_and_states():
    for platform, entities in gen.build()["entity"].items():
        for key, icons in entities.items():
            assert key in CONTRACT[platform], f"{platform}.{key} is not an entity"
            reg = gen.registers.BY_KEY.get(key)
            if reg is not None and reg.options and "state" in icons:
                assert set(icons["state"]) <= set(reg.options), key
